import json
from pathlib import Path
root = Path('products/services/nz-gets-offline-delivery')
for name in ('qualification.json', 'index-screen.json'):
    data = json.loads((root / name).read_text(encoding='utf-8'))
    if name == 'qualification.json':
        print(json.dumps({'artifact': name, 'evidence': data}, ensure_ascii=True)[:6500])
    else:
        links = data.get('notice_links', [])
        candidates = {}
        for href, title in links:
            if any(word in title.casefold() for word in ('spreadsheet', 'reconcil', 'migration', 'data quality', 'data cleansing', 'data validation', 'data conversion', 'records digitisation')):
                candidates.setdefault(href, title)
        print(json.dumps({'artifact': name, 'screened_link_occurrences': len(links), 'title_matches_only': candidates}, ensure_ascii=True))
